#!/usr/bin/env node
// Loads two years of a made-up sole trader's records (services/api/tests/fixtures/fy2025.json and
// fy2026.json, generated by fixtures/build.mjs) into a running Solo through the API, then prints each
// report's figures next to the expected ones.
//
//   npm run seed:annual                       through Vite (http://localhost:5173) to its API
//   SEED_BASE_URL=http://127.0.0.1:<port> npm run seed:annual   straight to an API, e.g. `npm run local:serve`
//
// There is no sign-in: the business is added for the server's owner. A server that requires a key (the
// desktop app's own) needs SEED_API_KEY. The same data drives the integration tests in
// services/api/tests/annual_reports.rs.
import { readFileSync } from 'node:fs';

const base = (process.env.SEED_BASE_URL ?? 'http://localhost:5173').replace(/\/$/, '');
const fixture = (name) => JSON.parse(readFileSync(new URL(`../services/api/tests/fixtures/${name}.json`, import.meta.url), 'utf8'));
const first = fixture('fy2025');
const years = [first, fixture('fy2026')];

async function call(method, path, body) {
  const response = await fetch(`${base}/api/v1${path}`, {
    method,
    headers: {
      'content-type': 'application/json',
      'x-client-kind': 'web',
      ...(process.env.SEED_API_KEY ? { 'x-api-key': process.env.SEED_API_KEY } : {}),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const json = response.status === 204 ? null : await response.json().catch(() => null);
  if (!response.ok) throw new Error(`${method} ${path} failed (${response.status}): ${JSON.stringify(json)}`);
  return json;
}

const business = await call('POST', '/businesses', { ...first.business, complete_onboarding: true });
const b = `/businesses/${business.id}`;
await call('PUT', `${b}/opening-balances`, first.opening_balances);
for (const asset of first.assets) await call('POST', `${b}/assets`, asset);
const customer = await call('POST', `${b}/customers`, first.customer);

/** Enters a year the way a user would, and posts its depreciation. */
async function enter(year) {
  for (const category of year.categories) await call('POST', `${b}/expense-categories`, category);
  const categories = await call('GET', `${b}/expense-categories`);
  for (const invoice of year.invoices) {
    const draft = await call('POST', `${b}/invoices`, {
      customer_id: customer.id,
      issue_date: invoice.issue_date,
      due_date: invoice.due_date,
      lines: invoice.lines.map((line) => ({ ...line, tax_treatment: 'standard' })),
    });
    await call('POST', `${b}/invoices/${draft.id}/issue`, {});
    await call('POST', `${b}/invoices/${draft.id}/payments`, { ...invoice.payment, method: 'bank_transfer' });
  }
  for (const { category, ...expense } of year.expenses) {
    await call('POST', `${b}/expenses`, { ...expense, category_id: categories.find((c) => c.name === category).id });
  }
  for (const movement of year.movements) await call('POST', `${b}/cash-movements`, movement);
  await call('POST', `${b}/assets/depreciation`, { year_end: year.year.to });
}

const dollars = (cents) => Math.sign(cents) * Math.floor((Math.abs(cents) + 50) / 100);
let mismatches = 0;

/** Prints each expected figure (a number, or [the year, the comparative]) beside Solo's. */
async function compare(year) {
  for (const kind of ['profit_and_loss', 'balance_sheet', 'equity_changes']) {
    const report = await call('GET', `${b}/reports/${kind}?from=${year.year.from}&to=${year.year.to}&basis=accrual`);
    const rows = report.sections.flatMap((s) => [...s.rows, ...(s.totals ? [s.totals] : [])]);
    console.log(`\n${report.title}, year to ${year.year.to}`);
    for (const [label, expected] of Object.entries(year.expected[kind])) {
      const wanted = Array.isArray(expected) ? expected : [expected];
      const row = rows.find((r) => r[0] === label);
      const actual = wanted.map((_, i) => (row ? dollars(row[i + 1]) : 0));
      const ok = actual.every((a, i) => a === wanted[i]);
      if (!ok) mismatches += 1;
      console.log(`  ${ok ? '✓' : '✗'} ${label.padEnd(32)} ${actual.join(' / ').padStart(20)}  (expected: ${wanted.join(' / ')})`);
    }
  }
}

for (const year of years) {
  await enter(year);
  await compare(year);
}

console.log(`${first.business.name} (FY2025 and FY2026) loaded.`);
console.log(mismatches ? `${mismatches} figure(s) differ from the expected ones.` : 'Every figure matches.');
process.exit(mismatches ? 1 : 0);
